"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('boundaries-lab'))return;L.init(['left','right'],()=>{const VL=L.range('left'),VR=L.range('right'),E=VL-VR,g=L.$('drawing');const a=L.plot(g,[{fn:x=>VL+(VR-VL)*x}],{xMax:1,yMin:-5,yMax:10,xLabel:'位置 x（m）；兩板間距 L=1 m',yLabel:'電位 V（V）',height:360});g.append(L.svg('text',{x:65,y:395,class:'svg-label'},'電場 E = '+L.fmt(E)+' V/m'),L.svg('text',{x:65,y:426,class:'svg-small'},E===0?'兩端同電位，沒有電位斜坡。':E<0?'場指向左方：由高電位往低電位。':'場指向右方：由高電位往低電位。'));if(E!==0){const x1=E<0?575:360,x2=E<0?360:575;g.append(L.svg('path',{d:`M${x1} 400H${x2}l${E<0?12:-12} -8m${E<0?-12:12} 8l${E<0?12:-12} 8`,stroke:'#cf604b','stroke-width':3,fill:'none'}));}L.text('result-primary',L.fmt((VL+VR)/2)+' V');L.text('result-secondary',L.fmt(E)+' V/m');L.text('feedback','左端 '+VL+' V、右端 '+VR+' V，把所有可能直線中的這一條選出來。斜率 dV/dx = '+L.fmt(VR-VL)+' V/m，所以電場 E=−dV/dx = '+L.fmt(E)+' V/m。'+(VL===VR?'兩端相同時，常數電位仍可不為零，但電場是零。':'把兩端一起加同一個常數，斜率與電場都不變。')+' 這是忽略平行板邊緣場的中央一維靜電近似。');});})();
